"""keigan/services/integration_settings_service.py: connection credentials cannot be redirected (V16) and secret names are generated by the server (V22)."""

from __future__ import annotations

import pytest
from sqlalchemy import select

from keigan.config import application_context
from keigan.config.database_config import open_session
from keigan.dtos.onboarding_dtos import IntegrationUpdateRequest, LogToolConnectionCreateRequest, LogToolConnectionUpdateRequest
from keigan.entities.application_entities import ExternalIntegration, LogToolConnection
from keigan.exceptions.keigan_exceptions import BusinessValidationException
from keigan.security.current_user import CurrentUser
from keigan.services.integration_settings_service import IntegrationSettingsService
from keigan.utils.outbound_url_policy import OutboundUrlPolicy
from support.telemetry_scope import create_scoped_application

pytestmark = pytest.mark.usefixtures("seed_context")

APPLICATION_ADMIN = CurrentUser(
    user_principal_name="admin@example.com", display_name="Admin", email_address=None, group_names=frozenset(), group_object_ids=frozenset(), is_keigan_admin=False
)
CREDENTIAL_REMOVED_MESSAGE = "The address or sign-in method changed, so the saved credential was removed. Enter the credential again."
PRIVATE_ADDRESS_MESSAGE = "This address points at a private or internal network, which Keigan does not call."


async def create_connection(application_id: str, **overrides: object) -> str:
    values: dict[str, object] = dict(
        tool_type="elastic", connection_name="Elastic", endpoint_url="https://elastic.example.com", authentication_method="api_key", credential_value="secret-api-key"
    )
    async with open_session() as session:
        response = await IntegrationSettingsService(session).create_log_tool_connection(APPLICATION_ADMIN, application_id, LogToolConnectionCreateRequest(**{**values, **overrides}))
    return response.log_tool_connection_id


async def update_connection(application_id: str, connection_id: str, **changes: object):
    async with open_session() as session:
        return await IntegrationSettingsService(session).update_log_tool_connection(APPLICATION_ADMIN, application_id, connection_id, LogToolConnectionUpdateRequest(**changes))


async def stored_credential(connection_id: str) -> str | None:
    async with open_session() as session:
        secret_name = (await session.get(LogToolConnection, connection_id)).credential_secret_name
    return await application_context.secret_store().get_secret_or_none(secret_name)


# ── V16: the credential stays with the endpoint it was entered for ─────────────
@pytest.mark.parametrize("changes", [{"endpoint_url": "https://attacker.example.com"}, {"authentication_method": "bearer_token"}])
async def test_changing_the_endpoint_or_sign_in_method_removes_the_stored_credential(changes: dict[str, str]) -> None:
    application = await create_scoped_application()
    connection_id = await create_connection(application.application_id)
    assert await stored_credential(connection_id) == "secret-api-key"
    response = await update_connection(application.application_id, connection_id, **changes)
    assert (response.has_credential, response.last_test_message, response.connection_status) == (False, CREDENTIAL_REMOVED_MESSAGE, "not_tested")
    assert await stored_credential(connection_id) is None


async def test_changing_the_datadog_site_removes_the_stored_credential() -> None:
    application = await create_scoped_application()
    connection_id = await create_connection(application.application_id, tool_type="datadog", endpoint_url=None, connection_configuration={"site": "datadoghq.com"})
    response = await update_connection(application.application_id, connection_id, connection_configuration={"site": "datadoghq.eu"})
    assert (response.has_credential, response.last_test_message) == (False, CREDENTIAL_REMOVED_MESSAGE)


async def test_saving_the_same_endpoint_again_keeps_the_credential() -> None:
    application = await create_scoped_application()
    connection_id = await create_connection(application.application_id)
    response = await update_connection(application.application_id, connection_id, connection_name="Renamed", endpoint_url="https://ELASTIC.example.com")
    assert response.has_credential is True
    assert await stored_credential(connection_id) == "secret-api-key"


async def test_new_credential_sent_with_a_new_endpoint_is_kept() -> None:
    application = await create_scoped_application()
    connection_id = await create_connection(application.application_id)
    response = await update_connection(application.application_id, connection_id, endpoint_url="https://other.example.com", credential_value="new-key")
    assert response.has_credential is True
    assert await stored_credential(connection_id) == "new-key"


# ── V16: outbound URL policy on save ───────────────────────────────────────────
async def test_connection_to_a_private_address_is_rejected_on_create_and_on_update() -> None:
    application = await create_scoped_application()
    async with open_session() as session:
        with pytest.raises(BusinessValidationException) as rejection:
            await IntegrationSettingsService(session).create_log_tool_connection(
                APPLICATION_ADMIN, application.application_id, LogToolConnectionCreateRequest(tool_type="elastic", connection_name="Internal", endpoint_url="https://10.0.0.5:9200")
            )
    assert rejection.value.extra["fieldErrors"] == [{"field": "endpointUrl", "message": PRIVATE_ADDRESS_MESSAGE}]
    connection_id = await create_connection(application.application_id)
    with pytest.raises(BusinessValidationException):
        await update_connection(application.application_id, connection_id, endpoint_url="https://kubernetes.default.svc")
    assert await stored_credential(connection_id) == "secret-api-key"


async def test_datadog_site_that_resolves_to_a_private_address_is_rejected(monkeypatch: pytest.MonkeyPatch) -> None:
    async def resolver(hostname: str) -> list[str]:
        return ["10.0.0.9"]

    monkeypatch.setattr(application_context, "outbound_url_policy", lambda: OutboundUrlPolicy(denied_host_suffixes=(".svc",), resolver=resolver))
    application = await create_scoped_application()
    async with open_session() as session:
        with pytest.raises(BusinessValidationException) as rejection:
            await IntegrationSettingsService(session).create_log_tool_connection(
                APPLICATION_ADMIN, application.application_id,
                LogToolConnectionCreateRequest(tool_type="datadog", connection_name="Datadog", connection_configuration={"site": "internal-dd.example"}),
            )
    assert rejection.value.extra["fieldErrors"] == [{"field": "connectionConfiguration.site", "message": PRIVATE_ADDRESS_MESSAGE}]


async def test_tool_without_a_reader_keeps_internal_endpoints_that_are_only_stored() -> None:
    application = await create_scoped_application()
    connection_id = await create_connection(application.application_id, tool_type="solarwinds", endpoint_url="https://orion.syd.corp.example:17778")
    assert connection_id


# ── V22: secret names are generated by the server ──────────────────────────────
INTEGRATION_CONFIGURATION = {"base_url": "https://cmdb.example.com", "authentication_method": "api_key"}


async def test_integration_secret_name_sent_by_the_client_is_ignored() -> None:
    application = await create_scoped_application()
    async with open_session() as session:
        response = await IntegrationSettingsService(session).save_integration(
            APPLICATION_ADMIN, application.application_id, "cmdb",
            IntegrationUpdateRequest.model_validate({
                "credentialSecretName": "servicenow-credential",
                "integrationConfiguration": {**INTEGRATION_CONFIGURATION, "credential_secret_name": "teams-bot-secret"},
            }),
        )
    assert response.credential_secret_name is None
    assert "credential_secret_name" not in response.integration_configuration


async def test_integration_credential_is_stored_under_a_generated_name_and_never_returned() -> None:
    application = await create_scoped_application()
    async with open_session() as session:
        response = await IntegrationSettingsService(session).save_integration(
            APPLICATION_ADMIN, application.application_id, "cmdb",
            IntegrationUpdateRequest(integration_configuration=INTEGRATION_CONFIGURATION, credential_value="cmdb-secret"),
        )
        row = await session.scalar(select(ExternalIntegration).where(ExternalIntegration.application_id == application.application_id))
    assert response.credential_secret_name.startswith("integration-cmdb-")
    assert await application_context.secret_store().get_secret_or_none(row.credential_secret_name) == "cmdb-secret"
    assert "cmdb-secret" not in response.model_dump_json()
